kernel void depthUpsample(texture2d<float, access::sample> depthLow [[texture(0)]],
                          texture2d<half, access::sample> guideLow [[texture(1)]],
                          texture2d<half, access::read> colorHi [[texture(2)]],
                          texture2d<float, access::write> dispOut [[texture(3)]],
                          constant UpsampleParams &P [[buffer(0)]],
                          uint2 gid [[thread_position_in_grid]])
