// ---------------------------------------------------------------------------
// Stereo synthesis: for each pixel of each eye, search the source scanline for the segment
// that lands here after the disparity shift; the nearest (largest disparity) wins, and
// disoccluded gaps are filled from the background side.
// Output: side-by-side texture (2*width x height), left eye first.
// ---------------------------------------------------------------------------
kernel void stereoSynth(texture2d<half, access::sample> color [[texture(0)]],
                        texture2d<float, access::read> disp [[texture(1)]],
                        texture2d<half, access::write> sbs [[texture(2)]],
                        constant StereoParams &P [[buffer(0)]],
                        uint2 gid [[thread_position_in_grid]])
{
    const int W = int(P.width), H = int(P.height);
    if (gid.x >= uint(2 * W) || gid.y >= uint(H)) return;
    int eye = gid.x >= uint(W) ? 1 : 0;
    if (P.swapEyes) eye = 1 - eye;
    // Positive disparity (near) shifts content right in the left eye and left in the right eye.
    const float s = (eye == 0) ? 0.5f : -0.5f;
    const int xo = int(gid.x) - ((gid.x >= uint(W)) ? W : 0);
    const int y = int(gid.y);
    const int R = int(ceil(P.maxDisp * 0.5f)) + 1;
    const int x0 = max(xo - R, 0), x1 = min(xo + R, W - 1);

    float bestD = -1e9f, bestSrc = 0.0f; bool found = false;
    float holeD = 1e9f, holeSrc = 0.0f; bool holeFound = false;

    float dPrev = disp.read(uint2(x0, y)).r;
    float pPrev = float(x0) + s * dPrev;
    const float xof = float(xo);
    for (int xs = x0; xs < x1; ++xs) {
        float dNext = disp.read(uint2(xs + 1, y)).r;
        float pNext = float(xs + 1) + s * dNext;
        float lo = min(pPrev, pNext), hi = max(pPrev, pNext);
        if (xof >= lo && xof < hi + 1e-4f) {
            float len = hi - lo;
            float t = (len > 1e-5f) ? (xof - pPrev) / (pNext - pPrev) : 0.0f;
            t = saturate(t);
            float dHere = mix(dPrev, dNext, t);
            if (len <= P.stretchThresh) {
                if (dHere > bestD) { bestD = dHere; bestSrc = float(xs) + t; found = true; }
            } else {
                float dBg = min(dPrev, dNext);
                if (dBg < holeD) { holeD = dBg; holeSrc = (dPrev < dNext) ? float(xs) : float(xs + 1); holeFound = true; }
            }
        }
        dPrev = dNext; pPrev = pNext;
    }
    float src = found ? bestSrc : (holeFound ? holeSrc : xof);
    half4 c = color.sample(linearClamp, float2((src + 0.5f) / float(W), (float(y) + 0.5f) / float(H)));
    c.a = 1.0h;
    sbs.write(c, gid);
}

